int main(void)
{
    unsigned seed;
    int bad = 0;
    for (seed = 0; seed < 12; seed++) {
        BYTE data[160];
        ldmState_t state;
        rawSeqStore_t store;
        ldmParams_t params;
        U32 strategy = 1 + (seed * 4) % 9;
        size_t size, last;
        U32 wrong;
        ldm_init_gear_table();
        size = build_input(data, seed);
        params.windowLog = 8 + seed % 3;
        params.hashLog = 5 + seed % 2;
        params.bucketSizeLog = params.minMatchLength = params.hashRateLog = 0;
        ZSTD_ldm_adjustParameters(&params, strategy);
        last = ldm_process(&state, &store, &params, data, 40, size);
        if (last == (size_t)-1) continue;
        wrong = ldm_replay(data, 40, size, &store, last);
        if (wrong != 0) bad |= 1 << (seed % 8);
    }
    (void)orig_main;
    return bad;
}
